insert into public.news_articles (legacy_id, slug, title, excerpt, body, sport, cover_url, cover_position, cover_orientation, match_id, author, read_time_minutes, status, published_at, category_id) values ('news-wac-nabi-2026-10', 'nasreddine-nabi-entraineur', '{"ar":"تعيين الإطار التونسي نصر الدين نابي مدرباً للفريق الأول","fr":"Le Tunisien Nasreddine Nabi nommé entraîneur de l’équipe première","en":"Tunisian coach Nasreddine Nabi appointed first-team head coach"}'::jsonb, '{"ar":"يعلن نادي الوداد الرياضي عن تعيين الإطار التونسي نصر الدين نابي مدربا للفريق الأول، وذلك إلى غاية نهاية الموسم الرياضي الحالي.","fr":"Le Wydad Athletic Club annonce la nomination du technicien tunisien Nasreddine Nabi au poste d’entraîneur de l’équipe première, jusqu’à la fin de la saison en cours.","en":"Wydad Athletic Club announces the appointment of Tunisian coach Nasreddine Nabi as first-team head coach until the end of the current season."}'::jsonb, '{"ar":"ويعكس هذا التعيين توجه النادي نحو الاستفادة من خبرة الإطار نصر الدين نابي وكفاءته التدريبية، لقيادة الفريق الأول خلال المرحلة المقبلة، والعمل على تطوير أدائه وتعزيز حضوره التنافسي في مختلف الاستحقاقات.\n\nوإذ يرحب نادي الوداد الرياضي بمدربه نصر الدين نابي، فإنه يتمنى له كامل التوفيق والنجاح في مهامه، والمساهمة في تحقيق الأهداف المسطرة والاستجابة لتطلعات الجماهير الودادية.","fr":"Cette nomination traduit la volonté du club de s’appuyer sur l’expérience et les compétences de Nasreddine Nabi pour diriger l’équipe première lors de la période à venir, améliorer ses performances et renforcer sa compétitivité dans toutes les compétitions.\n\nEn souhaitant la bienvenue à son entraîneur Nasreddine Nabi, le Wydad Athletic Club lui adresse tous ses vœux de réussite dans ses missions, pour atteindre les objectifs fixés et répondre aux attentes des supporters wydadis.","en":"The appointment reflects the club’s wish to draw on Nasreddine Nabi’s experience and coaching ability to lead the first team in the period ahead, improve its performances and strengthen its competitiveness across all competitions.\n\nIn welcoming its new coach Nasreddine Nabi, Wydad Athletic Club wishes him every success in his role, in reaching the objectives set and in meeting the expectations of the Wydad supporters."}'::jsonb, 'football', '/images/news/nasreddine-nabi-appointment.jpg', '28% 35%', null, null, 'Wydad Athletic Club', 1, 'published', '2026-10-22T17:00:00Z', (select id from public.categories where slug = 'club')) on conflict (legacy_id) do nothing;
insert into public.news_articles (legacy_id, slug, title, excerpt, body, sport, cover_url, cover_position, cover_orientation, match_id, author, read_time_minutes, status, published_at, category_id) values ('news-officials-uts-wac-2026', 'arbitres-touarga-wydad', '{"ar":"هشام التمسماني حكماً لمباراة إتحاد تواركة والوداد الرياضي","fr":"Hicham Temsamani au sifflet de Touarga – Wydad","en":"Hicham Temsamani to referee Touarga vs Wydad"}'::jsonb, '{"ar":"عُيّن هشام التمسماني لقيادة مباراة إتحاد تواركة والوداد الرياضي، يوم السبت 24 أكتوبر على الساعة السادسة مساءً، برسم الجولة الخامسة من البطولة الاحترافية.","fr":"Hicham Temsamani dirigera la rencontre entre l’Union Touarga Sport et le Wydad, samedi 24 octobre à 18h, pour la 5e journée de Botola Pro.","en":"Hicham Temsamani will take charge of Union Touarga Sport vs Wydad on Saturday 24 October at 6pm, on Botola Pro matchday 5."}'::jsonb, '{"ar":"وسيتواجد سليمان العاطفي في غرفة الفار.","fr":"Soulaimane El Atifi officiera dans la salle de la VAR.","en":"Soulaimane El Atifi will be in the VAR room."}'::jsonb, 'football', '/images/news/hicham-temsamani.jpg', '45% 25%', null, 'mt_468151508', 'Wydad Athletic Club', 1, 'published', '2026-10-22T14:00:00Z', (select id from public.categories where slug = 'club')) on conflict (legacy_id) do nothing;
insert into public.news_articles (legacy_id, slug, title, excerpt, body, sport, cover_url, cover_position, cover_orientation, match_id, author, read_time_minutes, status, published_at, category_id) values ('news-wac-coach-2026-10', 'paulo-sergio-depart-accord', '{"ar":"الوداد ينهي ارتباطه بالمدرب باولو سيرجيو بالتراضي","fr":"Le Wydad et Paulo Sérgio se séparent d’un commun accord","en":"Wydad and Paulo Sérgio part ways by mutual agreement"}'::jsonb, '{"ar":"يعلن نادي الوداد الرياضي عن توصله إلى اتفاق مع المدرب باولو سيرجيو بيريتو يقضي بفسخ العقد الذي يربط الطرفين بالتراضي.","fr":"Le Wydad Athletic Club annonce être parvenu à un accord avec l’entraîneur Paulo Sérgio pour mettre fin, à l’amiable, au contrat qui liait les deux parties.","en":"Wydad Athletic Club has reached an agreement with head coach Paulo Sérgio to terminate the contract between the two parties by mutual consent."}'::jsonb, '{"ar":"وبهذه المناسبة، يتقدم النادي بخالص الشكر والتقدير للمدرب على ما قدمه خلال فترة إشرافه على الفريق، متمنياً له كامل التوفيق والنجاح في مسيرته المهنية.","fr":"À cette occasion, le club adresse ses sincères remerciements à l’entraîneur pour le travail accompli durant sa période à la tête de l’équipe, et lui souhaite pleine réussite dans la suite de sa carrière.","en":"The club extends its sincere thanks and appreciation to the coach for his work during his time in charge of the team, and wishes him every success in the rest of his career."}'::jsonb, 'football', '/images/news/paulo-sergio-thank-you.jpg', '72% 22%', 'portrait', null, 'Wydad Athletic Club', 1, 'published', '2026-10-22T12:00:00Z', (select id from public.categories where slug = 'club')) on conflict (legacy_id) do nothing;
insert into public.news_articles (legacy_id, slug, title, excerpt, body, sport, cover_url, cover_position, cover_orientation, match_id, author, read_time_minutes, status, published_at, category_id) values ('news-wac-usat-2026', 'wydad-amal-tiznit-1-1', '{"ar":"تعثر جديد: الوداد يسقط في فخ التعادل أمام أمل تيزنيت","fr":"Nouveau faux pas : le Wydad tenu en échec par l''Amal Tiznit","en":"Another slip: Wydad held by Amal Tiznit"}'::jsonb, '{"ar":"اكتفى الوداد بالتعادل بهدف لمثله أمام أمل تيزنيت بملعب محمد الخامس، في الجولة الرابعة من البطولة الاحترافية.","fr":"Le Wydad a dû se contenter d''un nul 1-1 face à l''Amal Tiznit au complexe Mohammed V, lors de la 4e journée de Botola Pro.","en":"Wydad had to settle for a 1-1 draw against Amal Tiznit at the Mohammed V complex on Botola Pro matchday 4."}'::jsonb, '{"ar":"لم ينجح الوداد الرياضي في تحقيق الفوز أمام جماهيره، بعدما فرض عليه أمل تيزنيت التعادل بهدف لمثله على أرضية مركب محمد الخامس بالدار البيضاء، برسم الجولة الرابعة من البطولة الاحترافية.\n\nافتتح الضيوف التسجيل في الدقيقة 53 عن طريق زكرياء الصالحي من ضربة جزاء.\n\nوردّ الوداد بعد تسع دقائق فقط، حين عادل سيلفير غانفولا النتيجة في الدقيقة 62 من ضربة جزاء أيضاً.\n\nبهذه النتيجة يرفع الوداد رصيده إلى 5 نقاط في المركز التاسع، فيما يصل أمل تيزنيت إلى 4 نقاط في المركز الحادي عشر.","fr":"Le Wydad Athletic Club n''a pas réussi à s''imposer devant son public. Au complexe Mohammed V de Casablanca, les Rouges ont été accrochés par l''Amal Tiznit (1-1), en clôture de la 4e journée de Botola Pro.\n\nLes visiteurs ont frappé les premiers : à la 53e minute, Zakaria Salhi a transformé un penalty pour donner l''avantage à Tiznit.\n\nLa réaction est venue neuf minutes plus tard. À la 62e, Silvère Ganvoula a lui aussi converti un penalty pour remettre les deux équipes à égalité.\n\nAvec ce nul, le Wydad compte 5 points et pointe à la 9e place. L''Amal Tiznit passe à 4 unités, au 11e rang.","en":"Wydad Athletic Club could not get the win in front of their own fans. At the Mohammed V complex in Casablanca, the Reds were held 1-1 by Amal Tiznit on Botola Pro matchday 4.\n\nThe visitors struck first: Zakaria Salhi converted a penalty in the 53rd minute to put Tiznit ahead.\n\nWydad answered nine minutes later, with Silvère Ganvoula also scoring from the spot in the 62nd minute to level the game.\n\nThe draw takes Wydad to 5 points in 9th place, while Amal Tiznit move up to 4 points in 11th."}'::jsonb, 'football', '/images/news/wydad-amal-tiznit-lineup.jpg', 'center 78%', null, 'mt_371866534', 'Wydad Athletic Club', 2, 'published', '2026-10-18T22:15:00Z', (select id from public.categories where slug = 'match_report')) on conflict (legacy_id) do nothing;
