insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('swimming', '{"ar":"معسكر إعدادي ببوزنيقة","fr":"Stage de préparation à Bouznika","en":"Training camp in Bouznika"}'::jsonb, '{"ar":"من 19 إلى 24 أكتوبر 2026، يخوض سباحو الوداد معسكرا إعداديا بنادي CIH ببوزنيقة: تداريب مكثفة وتقنية وإعداد بدني وروح جماعية، تحت إشراف المدرب الرئيسي أيمن رياضي رفقة كريمة المرحر ومنصف الدغاي.","fr":"Du 19 au 24 octobre 2026, les nageurs du Wydad sont en stage au Club CIH de Bouznika : entraînements intensifs, technique, préparation physique et cohésion, sous la direction du head coach Aymen Riadi, avec Karima El Marhar et Monsef Daghai.","en":"From 19 to 24 October 2026, Wydad’s swimmers are at Club CIH in Bouznika: intensive sessions, technique, conditioning and team spirit, led by head coach Aymen Riadi with Karima El Marhar and Monsef Daghai."}'::jsonb, '/images/sections/swimming/Deqp79bMoVb.jpg', 'https://www.instagram.com/p/Deqp79bMoVb/', null, '2026-10-19', 'published', 0, md5('highlight:swimming:stage')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('swimming', '{"ar":"خديجة أبوطيب، معالجة أبطالنا","fr":"Khadija Aboutaib, kiné de nos champions","en":"Khadija Aboutaib, our champions’ physio"}'::jsonb, '{"ar":"يعزز الفرع تعاونه مع المعالجة الفيزيائية خديجة أبوطيب، الوفية للنادي منذ سنوات، لمواكبة السباحين في المنافسات والتداريب والاسترجاع.","fr":"La section renforce sa collaboration avec Khadija Aboutaib, kinésithérapeute fidèle au club depuis de nombreuses années, pour le suivi des nageurs en compétition, à l’entraînement et en récupération.","en":"The section strengthens its partnership with physiotherapist Khadija Aboutaib, at the club’s side for many years, to follow swimmers in competition, training and recovery."}'::jsonb, '/images/sections/swimming/DeeeOEmjODc.jpg', 'https://www.instagram.com/p/DeeeOEmjODc/', null, '2026-10-14', 'published', 10, md5('highlight:swimming:physio')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('swimming', '{"ar":"دوليان سابقان","fr":"Deux anciens internationaux","en":"Two former internationals"}'::jsonb, '{"ar":"بدر الدين بوشويرب، الرئيس المنتدب للفرع ورئيس عصبة الدار البيضاء-سطات، وإبراهيم الطحسي، المسؤول الجهوي عن المسابح بصونارجيس، سبق لهما السباحة ولعب كرة الماء مع المنتخب المغربي.","fr":"Badreddine Bouchouirab, président délégué de la section et président de la Ligue Casablanca-Settat, et Brahim Tahsi, responsable aquatique régional à la SONARGES, ont tous deux nagé et joué au water-polo pour le Maroc.","en":"Badreddine Bouchouirab, the section’s delegate president and head of the Casablanca-Settat league, and Brahim Tahsi, regional aquatics manager at SONARGES, both swam and played water polo for Morocco."}'::jsonb, '/images/sections/swimming/DePp56FsFQi.jpg', 'https://www.instagram.com/p/DePp56FsFQi/', null, '2026-10-08', 'published', 20, md5('highlight:swimming:internationals')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('boxing', '{"ar":"طه موطي وصيف بطل المغرب","fr":"Taha Mouti vice-champion du Maroc","en":"Taha Mouti, Moroccan runner-up"}'::jsonb, '{"ar":"يهنئ الوداد الرياضي بطله طه موطي بمناسبة إحرازه المرتبة الثانية في بطولة المغرب، والقادم أفضل.","fr":"Le Wydad félicite son boxeur Taha Mouti, médaillé d’argent au championnat du Maroc. Le meilleur reste à venir.","en":"Wydad congratulates boxer Taha Mouti on his silver medal at the Moroccan championship. The best is yet to come."}'::jsonb, '/images/sections/boxing/Dekt2ivCDMg.jpg', 'https://www.instagram.com/p/Dekt2ivCDMg/', null, '2026-10-16', 'published', 0, md5('highlight:boxing:mouti')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('boxing', '{"ar":"تقنية وانضباط","fr":"Technique & discipline","en":"Technique & discipline"}'::jsonb, '{"ar":"نزالات تدريبية وعمل تقني وإعداد بدني: يوميات فرع الملاكمة على حسابه الرسمي.","fr":"Séances de sparring, travail technique et préparation physique : le quotidien de la section boxe, à suivre sur son compte officiel.","en":"Sparring, technical work and conditioning: the boxing section’s daily routine, on its official account."}'::jsonb, '/images/sections/boxing/DemJbrYNKl3.jpg', 'https://www.instagram.com/p/DemJbrYNKl3/', null, '2026-10-17', 'published', 10, md5('highlight:boxing:training')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('fencing', '{"ar":"هبة الزعيمي في أولمبياد الشباب داكار 2026","fr":"Hiba Zaimi aux JOJ Dakar 2026","en":"Hiba Zaimi at the Dakar 2026 YOG"}'::jsonb, '{"ar":"في سنتها الأولى بفئة الفتيان أقل من 15 سنة، ستمثل هبة الزعيمي المغرب في الألعاب الأولمبية للشباب داكار 2026 في الشيش سيدات، فئة الشبان أقل من 20 سنة.","fr":"Cadette U15 de première année, Hiba Zaimi représentera le Maroc aux Jeux olympiques de la jeunesse de Dakar 2026 au fleuret féminin, dans la catégorie juniors U20.","en":"An under-15 cadet in her first year, Hiba Zaimi will represent Morocco at the Dakar 2026 Youth Olympic Games in women’s foil, in the under-20 junior category."}'::jsonb, '/images/sections/fencing/DewaoIpMUUV.jpg', 'https://www.instagram.com/p/DewaoIpMUUV/', null, '2026-10-21', 'published', 0, md5('highlight:fencing:zaimi')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('fencing', '{"ar":"تكوين في مكافحة المنشطات","fr":"Formation antidopage ADEL","en":"ADEL anti-doping training"}'::jsonb, '{"ar":"تابع مبارزونا بالرباط تكوين ADEL للوكالة المغربية لمكافحة المنشطات، رفقة أوليائهم ومدربهم، استعدادا لداكار 2026.","fr":"Nos escrimeurs ont suivi à Rabat la formation ADEL de l’Agence marocaine antidopage (AMAD), avec leurs parents et leur entraîneur, en route vers Dakar 2026.","en":"Our fencers took the ADEL course of the Moroccan Anti-Doping Agency (AMAD) in Rabat with their parents and coach, on the road to Dakar 2026."}'::jsonb, '/images/sections/fencing/DezWDfiDCCV.jpg', 'https://www.instagram.com/p/DezWDfiDCCV/', null, '2026-10-22', 'published', 10, md5('highlight:fencing:antidoping')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('fencing', '{"ar":"الخلف مضمون","fr":"La relève est assurée","en":"The future is in good hands"}'::jsonb, '{"ar":"بطلات الفرع الصغيرات يرفعن منذ الآن ألوان الأحمر والأبيض عاليا.","fr":"Les petites championnes de la section portent déjà haut les couleurs rouge et blanc sur les pistes.","en":"The section’s young champions already fly the red and white colours on the piste."}'::jsonb, '/images/sections/fencing/Deh223uDCr0.jpg', 'https://www.instagram.com/p/Deh223uDCr0/', null, '2026-10-15', 'published', 20, md5('highlight:fencing:next_gen')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('handball', '{"ar":"تجديد عقد عبد المجيد الزاولي","fr":"Abdelmajid Zaouli prolongé","en":"Abdelmajid Zaouli extended"}'::jsonb, '{"ar":"جدد المدرب عبد المجيد الزاولي عقده مع فرع كرة اليد لموسم واحد قابل للتجديد، تعزيزا لاستقرار الفريق الأول.","fr":"L’entraîneur Abdelmajid Zaouli renouvelle son contrat avec la section handball pour une saison, renouvelable, afin de renforcer la stabilité de l’équipe première.","en":"Coach Abdelmajid Zaouli renews with the handball section for one season, renewable, to keep the first team stable."}'::jsonb, '/images/sections/handball/Ddrmu6qDp4V.jpg', 'https://www.instagram.com/p/Ddrmu6qDp4V/', null, '2026-09-24', 'published', 0, md5('highlight:handball:coach')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('academy', '{"ar":"التسجيل مفتوح لموسم 2026/2027","fr":"Inscriptions 2026/2027 ouvertes","en":"2026/27 registrations open"}'::jsonb, '{"ar":"أكاديمية الوداد لكرة القدم تفتح باب التسجيل لموسم 2026/2027: هوية جديدة ونفس الحمض الأصلي، لصناعة ولاد المدرسة القادمين.","fr":"La Wydad Football Academy ouvre ses inscriptions pour la saison 2026/2027 : nouvelle identité, même ADN, pour former les prochains Wlad Al Madrassa.","en":"Wydad Football Academy opens registrations for the 2026/27 season: a new identity, the same DNA, to raise the next Wlad Al Madrassa."}'::jsonb, '/images/sections/academy/Dc_XJqnDm8D.jpg', 'https://app.atlasclubmorocco.com/inscription/INS-Z9UZL5', '{"ar":"التسجيل","fr":"S’inscrire","en":"Register"}'::jsonb, '2026-09-07', 'published', 0, md5('highlight:academy:registrations')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('academy', '{"ar":"مخيم الوداد الصيفي","fr":"Wydad Summer Camp","en":"Wydad Summer Camp"}'::jsonb, '{"ar":"نسخة أولى ناجحة في يوليوز 2026: كرة قدم وورشات واكتشافات وابتسامات كثيرة للمخيمين الصغار.","fr":"Une première édition réussie en juillet 2026 : football, ateliers, découvertes et beaucoup de sourires pour les jeunes campeurs.","en":"A successful first edition in July 2026: football, workshops, discoveries and plenty of smiles for the young campers."}'::jsonb, '/images/sections/academy/DbAnzQzPps6.jpg', 'https://www.instagram.com/p/DbAnzQzPps6/', null, '2026-07-20', 'published', 10, md5('highlight:academy:summer_camp')::uuid) on conflict (id) do nothing;
insert into public.section_highlights (section, title, text, image_url, source_url, cta_label, published_on, status, sort, id) values ('basketball', '{"ar":"مدرسة الوداد لكرة السلة","fr":"École de basket du Wydad","en":"Wydad basketball school"}'::jsonb, '{"ar":"أكاديمية الوداد لكرة السلة تفتح باب التسجيل. للمعلومات: 0662715685.","fr":"L’Académie de basketball du Wydad ouvre ses inscriptions. Infos : 06 62 71 56 85.","en":"Wydad’s basketball academy is open for registration. Info: +212 6 62 71 56 85."}'::jsonb, '/images/sections/basketball/Dee8jhVRSYE.jpg', 'https://wydadbasketball.ma/inscription/', '{"ar":"التسجيل","fr":"S’inscrire","en":"Register"}'::jsonb, '2026-10-14', 'published', 0, md5('highlight:basketball:academy')::uuid) on conflict (id) do nothing;
insert into public.membership_offers (slug, tier, name, description, price_amount, currency, benefits, image_url, availability, status) values ('gold', 'gold', '{"ar":"Gold Membership","fr":"Gold Membership","en":"Gold Membership"}'::jsonb, '{"ar":"أُطلقت خلال فترة الإعداد لموسم 2026-2027، وتعد العضوية الذهبية أكثر عضويات الوداد الرياضي حصرية: بطاقة ذهبية مرقمة مخصصة لدائرة ضيقة جداً من الأعضاء.","fr":"Lancée lors de la présaison 2026-27, la Gold Membership est l’adhésion la plus exclusive du Wydad Athletic Club : une carte d’or numérotée, réservée à un cercle très restreint de membres.","en":"Launched in the 2026-27 preseason, the Gold Membership is Wydad Athletic Club’s most exclusive membership: a numbered gold card reserved for a very small circle of members."}'::jsonb, 1000000, 'MAD', '[{"ar":"مقصورة خاصة بالملعب","fr":"Loge privée au stade","en":"Private stadium box"},{"ar":"ضيافة متميزة أيام المباريات","fr":"Hospitalité premium les jours de match","en":"Premium matchday hospitality"},{"ar":"تذكارات حصرية من المباريات","fr":"Souvenirs de match exclusifs","en":"Exclusive match memorabilia"},{"ar":"أولوية في تذاكر المباريات خارج الميدان","fr":"Priorité sur les billets à l’extérieur","en":"Priority away match tickets"},{"ar":"تجارب حصرية مع الفريق","fr":"Expériences exclusives avec l’équipe","en":"Exclusive team experiences"},{"ar":"أولوية الحصول على القمصان الرسمية","fr":"Accès prioritaire aux maillots officiels","en":"Official jersey priority access"},{"ar":"فعاليات وحفلات الشركاء","fr":"Événements et cérémonies partenaires","en":"Partner events & ceremonies"},{"ar":"امتيازات حصرية للأعضاء الذهبيين","fr":"Privilèges exclusifs Gold Member","en":"Exclusive Gold Member privileges"}]'::jsonb, '/images/membership/gold-membership.jpg', 'available', 'published') on conflict (slug) do nothing;
